//! `:help` / `Space ?` buffer decoration (0088 §2, U10; 0112 §4): the
//! help text and its typed lines are generated by `editor/help`; here
//! each line gets house style by its [`LineKind`]. Key cells are lexed
//! by `keymap::notation` and inked per token — plain keys in the accent,
//! named keys, chords and placeholders in their own syntax inks,
//! separators muted — on the base plane, with no keycap slab. The
//! spans' concatenated content keeps the buffer line's exact bytes, so
//! search, yank and the caret keep reading the real buffer.

use ratatui::style::{Modifier, Style};
use ratatui::text::Span;

use super::style::Tokens;
use crate::editor::help::{Cell, HelpPage, LineKind};
use crate::keymap::notation::{self, Token, TokenKind};

/// A token's style (§4.1).
fn ink(t: &Tokens, kind: TokenKind) -> Style {
    let bold = |color| Style::default().fg(color).add_modifier(Modifier::BOLD);
    match kind {
        TokenKind::Key | TokenKind::Command => bold(t.accent),
        TokenKind::Named => bold(t.syn.link),
        TokenKind::Chord => bold(t.syn.r#type),
        TokenKind::Placeholder => Style::default().fg(t.syn.string),
        TokenKind::Separator => Style::default().fg(t.muted),
        TokenKind::Tail => Style::default().fg(t.accent),
        TokenKind::Space => Style::default(),
    }
}

fn inked<'a>(t: &Tokens, tokens: impl Iterator<Item = Token<'a>>, out: &mut Vec<Span<'static>>) {
    out.extend(tokens.map(|token| Span::styled(token.text.to_string(), ink(t, token.kind))));
}

/// A key cell, read by what it holds.
fn cell_spans(t: &Tokens, cell: Cell, text: &str, out: &mut Vec<Span<'static>>) {
    match cell {
        Cell::Keys => inked(t, notation::keys(text), out),
        Cell::Command => inked(t, notation::command(text), out),
        Cell::Filter => inked(t, notation::filter(text), out),
        Cell::Label => out.push(Span::styled(
            text.to_string(),
            Style::default().fg(t.secondary),
        )),
    }
}

/// `━ Title ━` / `─ Title ─`: the glyphs faint, the rule run to the
/// pane's text width.
fn heading(t: &Tokens, text: &str, glyph: &str, title: Style, width: usize) -> Vec<Span<'static>> {
    let faint = Style::default().fg(t.faint);
    let lead = format!("{glyph} ");
    let rest = text.strip_prefix(&lead).unwrap_or(text);
    let end = rest.find(&format!(" {glyph}")).unwrap_or(rest.len());
    let (name, rule) = rest.split_at(end);
    let pad = width.saturating_sub(text.chars().count());
    vec![
        Span::styled(lead, faint),
        Span::styled(name.to_string(), title),
        Span::styled(format!("{rule}{}", glyph.repeat(pad)), faint),
    ]
}

/// The first line: the active section a filled chip (its name and one
/// cell either side), the rest muted.
fn tabs(t: &Tokens, page: &HelpPage, text: &str, active: usize) -> Vec<Span<'static>> {
    let muted = Style::default().fg(t.muted);
    let chip = page
        .tabs
        .get(active)
        .map(|tab| (tab.name.start.saturating_sub(1), tab.name.end + 1))
        .filter(|&(_, end)| end <= text.len());
    let Some((start, end)) = chip else {
        return vec![Span::styled(text.to_string(), muted)];
    };
    let chip = Style::default()
        .fg(t.on_accent)
        .bg(t.accent)
        .add_modifier(Modifier::BOLD);
    vec![
        Span::styled(text[..start].to_string(), muted),
        Span::styled(text[start..end].to_string(), chip),
        Span::styled(text[end..].to_string(), muted),
    ]
}

/// The hints: `strop {version}` bold, the key runs lexed, the words and
/// `·` muted.
fn hints(t: &Tokens, keys: &[std::ops::Range<usize>], text: &str) -> Vec<Span<'static>> {
    let muted = Style::default().fg(t.muted);
    let name_start = text.len() - text.trim_start().len();
    let name_end = text.find(" · ").unwrap_or(text.len());
    let mut out = vec![
        Span::raw(text[..name_start].to_string()),
        Span::styled(
            text[name_start..name_end].to_string(),
            Style::default().fg(t.text).add_modifier(Modifier::BOLD),
        ),
    ];
    let mut at = name_end;
    for range in keys {
        let Some(run) = text.get(range.clone()).filter(|_| range.start >= at) else {
            continue;
        };
        out.push(Span::styled(text[at..range.start].to_string(), muted));
        inked(t, notation::keys(run), &mut out);
        at = range.end;
    }
    out.push(Span::styled(text[at..].to_string(), muted));
    out
}

/// One help line's spans; `width` is the pane's text width, `active`
/// the section that holds the pane's cursor.
pub(crate) fn line_spans(
    t: &Tokens,
    page: &HelpPage,
    line: usize,
    text: &str,
    width: usize,
    active: usize,
) -> Vec<Span<'static>> {
    let body = Style::default().fg(t.text);
    match page.lines.get(line) {
        Some(LineKind::Tabs) => tabs(t, page, text, active),
        Some(LineKind::Hints { keys }) => hints(t, keys, text),
        Some(LineKind::TabHeading) => heading(
            t,
            text,
            "━",
            Style::default().fg(t.accent).add_modifier(Modifier::BOLD),
            width,
        ),
        Some(LineKind::Heading) => heading(t, text, "─", body.add_modifier(Modifier::BOLD), width),
        // a planned row is one quiet ink, its keys not inked
        Some(LineKind::Entry { planned: true, .. } | LineKind::Continuation { planned: true }) => {
            vec![Span::styled(
                text.to_string(),
                Style::default().fg(t.muted).add_modifier(Modifier::ITALIC),
            )]
        }
        Some(LineKind::Entry { cell, keys, .. }) if keys.end <= text.len() => {
            let desc = text[keys.end..]
                .find(|c: char| c != ' ')
                .map_or(text.len(), |at| keys.end + at);
            let mut out = vec![Span::raw(text[..keys.start].to_string())];
            cell_spans(t, *cell, &text[keys.clone()], &mut out);
            out.push(Span::raw(text[keys.end..desc].to_string()));
            out.push(Span::styled(text[desc..].to_string(), body));
            out
        }
        _ => vec![Span::styled(text.to_string(), body)],
    }
}

